'use client';

import Link from 'next/link';
import Image from 'next/image';
import { useLanguage } from '@/contexts/LanguageContext';
import { usePathname } from 'next/navigation';

export default function Header() {
  const { t, language } = useLanguage();
  const pathname = usePathname();

  return (
    <header className="bg-white border-b border-gray-200">
      <nav className="container mx-auto px-4 h-[72px] flex items-center">
        <div className="flex w-full items-center justify-between">

          {/* Logo */}
          <div className="-ml-4">
            <Link
              href={`/${language}`}
              className="flex items-center hover:opacity-80 transition-opacity"
            >
              <Image
                src="/images/logo/logo.png"
                alt="Ahmed Abdullah Nana Logo"
                width={400}
                height={120}
                className="h-20 md:h-24 lg:h-[120px] xl:h-32 w-auto object-contain"
                priority
              />
            </Link>
          </div>

          {/* Navigation + Language */}
          <div className="flex items-center gap-6">
            <ul className="hidden md:flex items-center gap-6">
              <li>
                <Link
                  href={`/${language}`}
                  className="text-gray-700 hover:text-green-700 transition-colors"
                >
                  {t('nav.home')}
                </Link>
              </li>
              <li>
                <Link
                  href={`/${language}/about`}
                  className="text-gray-700 hover:text-green-700 transition-colors"
                >
                  {t('nav.about')}
                </Link>
              </li>
              <li>
                <Link
                  href={`/${language}/products`}
                  className="text-gray-700 hover:text-green-700 transition-colors"
                >
                  {t('nav.products')}
                </Link>
              </li>
              <li>
                <Link
                  href={`/${language}/export`}
                  className="text-gray-700 hover:text-green-700 transition-colors"
                >
                  {t('nav.export')}
                </Link>
              </li>
              <li>
                <Link
                  href={`/${language}/quality`}
                  className="text-gray-700 hover:text-green-700 transition-colors"
                >
                  {t('nav.quality')}
                </Link>
              </li>
              <li>
                <Link
                  href={`/${language}/contact`}
                  className="text-gray-700 hover:text-green-700 transition-colors"
                >
                  {t('nav.contact')}
                </Link>
              </li>
            </ul>

            {/* Language Switch */}
            <div className="flex items-center gap-1 border-l border-gray-300 pl-4">
              <button
                onClick={() =>
                  (window.location.href = pathname.replace(/^\/[^/]+/, '/en'))
                }
                className={`px-2 py-1 text-sm rounded transition-colors ${
                  language === 'en'
                    ? 'bg-green-700 text-white'
                    : 'text-gray-700 hover:text-green-700'
                }`}
              >
                EN
              </button>
              <button
                onClick={() =>
                  (window.location.href = pathname.replace(/^\/[^/]+/, '/ar'))
                }
                className={`px-2 py-1 text-sm rounded transition-colors ${
                  language === 'ar'
                    ? 'bg-green-700 text-white'
                    : 'text-gray-700 hover:text-green-700'
                }`}
              >
                AR
              </button>
            </div>
          </div>

        </div>
      </nav>
    </header>
  );
}
